DECLARE @now7 DATETIME2(7) = SYSDATETIME();

SELECT
    @now7                                                AS full_precision,
    CAST(@now7 AS DATETIME2(3))                          AS milliseconds,
    CAST(@now7 AS DATETIME2(0))                          AS whole_seconds,
    CAST('2024-02-29T23:59:59.9999999' AS DATETIME2(7))  AS leap_day_ok;
